(function(root){
'use strict';
const E=root.NexusEngine,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avatarNames={arif:'ALFA',airis:'NOVA',faris:'BYTE',sara:'AURA'};
const world=document.createElement('section');world.id='safe-world';world.className='world';world.hidden=true;world.setAttribute('role','dialog');world.setAttribute('aria-modal','true');world.setAttribute('aria-label','Dunia SKUAD S.A.F.E.');document.body.append(world);
let profile=null,engine=null,lesson=0,controller=null,view='maps',feedback='',audioActive=false;
function read(k){try{return localStorage.getItem(k)}catch{return null}}function write(k,v){try{localStorage.setItem(k,v)}catch{}}
function save(){if(profile)write('safe-nexus-v1:'+profile.id,JSON.stringify(engine.snapshot()))}
function stopAudio(){if('speechSynthesis'in root)root.speechSynthesis.cancel();audioActive=false}
function stopCamera(){controller?.stop();controller=null}
function button(label,act,kind='',extra=''){return `<button class="w-button ${kind}" data-action="${act}" ${extra}>${label}</button>`}
function header(){return `<header class="w-header"><div class="w-profile"><img src="assets/${profile.avatar}-action.png" alt=""><span><small>SKUAD S.A.F.E. ${profile.classroom?'· '+esc(profile.classroom):''}</small><b>${esc(profile.name)}</b></span></div><div class="w-actions">${view==='maps'?button('Tukar watak','exit'):button('‹ Peta utama','maps')}<span class="mode-label">${engine.hasBadge()?'1':'0'} / 4 lencana</span></div></header><div class="w-body" id="w-body"></div>`}
function mount(next){stopCamera();stopAudio();view=next;world.dataset.view=next;world.innerHTML=header();const b=$('#w-body');return b}
function focus(){requestAnimationFrame(()=>{world.querySelector('h1,h2')?.setAttribute('tabindex','-1');world.querySelector('h1,h2')?.focus({preventScroll:true})})}
function icon(name){const paths={shield:'M12 2 21 6v7c0 5-9 9-9 9S3 18 3 13V6Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5Zm7 4v3',sound:'M3 9h4l5-5v16l-5-5H3Zm13-2q6 5 0 10m3-13q9 8 0 16',cup:'M7 3h10v7a5 5 0 0 1-10 0Zm0 2H3v4q0 5 5 5m9-9h4v4q0 5-5 5m-4 1v6m-4 0h8',certificate:'M5 2h11l4 4v16H5Zm4 6h6m-6 4h7m-7 4h4',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 3v1'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`}
function notice(){mount('notice').innerHTML=`<div class="notice-card w-glass"><div class="notice-emblem">${icon('shield')}</div><p class="w-kicker">SELAMAT DATANG KE SKUAD S.A.F.E.</p><h1 class="w-title">Misi kamu bermula di sini!</h1><p>Belajar mengenali buli, menjaga perasaan rakan dan bertindak dengan selamat.</p><div class="notice-steps"><span>01 <b>Belajar</b></span><span>02 <b>Cabaran</b></span><span>03 <b>Lencana</b></span></div><p class="notice-small">Kemajuan disimpan pada peranti ini. Kamera hanya digunakan jika kamu memilih mod AR. Kamu juga boleh menggunakan mod sentuhan.</p>${button('Teruskan →','maps','primary')}<button class="notice-back" data-action="exit">Tukar watak</button></div>`;focus()}
function mapGrid(){const body=mount('maps'),count=engine.hasBadge()?1:0;body.innerHTML=`<div class="mission-dashboard"><header class="dashboard-header"><div class="safe-brand"><span>${icon('shield')}</span><div><small>SKUAD</small><b>S.A.F.E.</b></div></div><div class="dashboard-tools"><button data-action="welcome-audio" aria-label="Dengar panduan">${icon('sound')}</button><button data-action="help" aria-label="Bantuan">${icon('help')}</button><button data-action="exit" class="change-avatar">Tukar watak</button></div></header><section class="dashboard-hero"><div class="hero-copy"><div class="hello-glass"><img src="assets/${profile.avatar}-action.png" alt=""><div><h1>Hai, ${esc(profile.name)}!</h1><p>Sedia menjadi wira sekolah?</p></div></div><h2>Misi Sekolah <em>Selamat</em></h2><p class="hero-tagline">Kenali buli. Lindungi rakan.</p></div><img class="dashboard-avatar" src="assets/${profile.avatar}-action.png" alt="${esc(avatarNames[profile.avatar])} — watak pilihan kamu"></section><section class="mission-progress" aria-label="${count} daripada empat lencana"><div><b>Kemajuan Misi</b><p><strong>${count}/4</strong> Lencana</p></div><div class="progress-shields">${E.maps.map((m,i)=>`<span class="${i<count?'earned':''}" title="${m.badge}" aria-label="${m.badge}: ${i<count?'diperoleh':'belum diperoleh'}">${icon('shield')}</span>`).join('')}</div></section><section class="dashboard-maps"><h2>${icon('map')} Pilih Peta Misi</h2><div class="mission-map-grid">${E.maps.map((m,i)=>{const unlocked=engine.unlocked(i),complete=i===0&&count;return `<button class="mission-map tile-${i} ${complete?'completed ':''}${unlocked?'available':'locked'}" data-map="${i}" aria-disabled="${!unlocked}" aria-label="${m.name}, ${unlocked?'boleh dibuka':'berkunci'}" style="--delay:-${i*.8}s"><div class="tile-heading"><h3>${m.name}</h3></div>${!unlocked?`<span class="tile-lock">${icon('lock')}</span>`:''}<img src="assets/${m.file}" alt="Pulau ${m.name}">${complete?'<span class="tile-check" aria-label="Selesai">✓</span>':''}</button>`}).join('')}</div><p class="dashboard-status" id="map-note" role="status" aria-live="polite">${count?'CYBER GRID telah dibuka!':'Selesaikan NEXUS untuk membuka peta seterusnya.'}</p></section><button class="mission-start" data-action="${count?'cyber':'intro'}">▶ &nbsp; ${count?'TEROKAI CYBER GRID':'MULAKAN MISI NEXUS'} <span>›</span></button><nav class="dashboard-nav" aria-label="Navigasi misi"><button class="active" data-action="maps" aria-current="page">${icon('map')}<span>Misi</span></button><button data-action="collection">${icon('cup')}<span>Lencana</span></button><button data-action="certificate">${icon('certificate')}<span>Sijil</span></button></nav><p class="dashboard-footer">Belajar → Cabaran → Lencana → Sijil</p></div>`;focus()}
function infoPanel(kind){const body=mount(kind);const earned=engine.hasBadge();body.innerHTML=`<article class="dashboard-info w-glass"><div class="notice-emblem">${icon(kind==='collection'?'cup':kind==='certificate'?'certificate':'help')}</div><h1 class="w-title">${kind==='collection'?'Koleksi Lencana':kind==='certificate'?'Sijil Wira Sekolah':'Panduan Misi'}</h1>${kind==='collection'?`<div class="collection-list">${E.maps.map((m,i)=>`<div class="${i===0&&earned?'earned':''}">${icon('shield')}<span><b>${m.badge}</b><small>${m.name} · ${i===0&&earned?'Telah diperoleh':'Belum diperoleh'}</small></span></div>`).join('')}</div>`:kind==='certificate'?`<p>Kumpulkan keempat-empat lencana untuk membuka sijil digital kamu.</p><p><strong>${earned?1:0}/4 lencana diperoleh</strong></p><p>Misi peta 2–4 sedang disiapkan. Sijil belum tersedia.</p>`:'<p>Mulakan di NEXUS. Baca tiga kad pembelajaran, kemudian selesaikan cabaran untuk memperoleh lencana dan membuka peta seterusnya.</p><p>Pilih mod sentuhan atau gunakan kamera dalam cabaran AR. Minta bantuan guru jika diperlukan.</p>'}${button('Kembali ke misi','maps','primary')}</article>`;focus()}
function welcomeAudio(){const note=$('#map-note');if(!('speechSynthesis'in root)||!('SpeechSynthesisUtterance'in root)){note.textContent='Audio tidak tersedia. Mulakan di NEXUS dan ikuti panduan pada skrin.';return}stopAudio();const u=new SpeechSynthesisUtterance('Hai, '+profile.name+'. Selamat datang ke Misi Sekolah Selamat. Pilih NEXUS untuk memulakan misi. Kenali buli. Lindungi rakan.');u.lang='ms-MY';u.rate=.9;u.onerror=()=>{if(view==='maps')$('#map-note').textContent='Audio belum tersedia pada peranti ini.'};speechSynthesis.speak(u)}
function intro(){engine.start();save();const body=mount('intro'),p=engine.snapshot();body.innerHTML=`<div class="module-layout"><div class="nexus-scene"><img class="map-scene" src="assets/Peta_1_NEXUS.png" alt="Peta NEXUS dengan empat stesen pembelajaran dan cabaran"><img class="scene-hero" src="assets/${profile.avatar}-action.png" alt="Karakter pilihan kamu">${[0,1,2,3].map((i)=>`<button class="station s${i+1} ${i<3&&p.learned.includes(i)?'done':''}" data-station="${i}" aria-label="${i<3?'Kad pembelajaran '+(i+1):'Cabaran NEXUS SCAN'}">${i<3?i+1:'✦'}</button>`).join('')}</div><div class="intro-panel w-glass"><p class="w-kicker">MODUL 01 · KENALI BULI</p><h1 class="w-title">Selamat datang<br>ke NEXUS!</h1><p class="w-sub">Di sini, kamu akan belajar mengenali buli dan membezakan buli, gurauan serta konflik.</p><p class="w-sub">Selesaikan pembelajaran dan cabaran untuk memperoleh <strong>Lencana Mata Bijak!</strong></p><div class="mission-summary"><span>3 kad ringkas</span><span>5 situasi</span><span>Sentuhan atau kamera</span></div><div class="intro-cta">${button(p.learned.length?'SAMBUNG MISI →':'MULA MISI →','learn','primary')}${p.learned.length===3?button('NEXUS SCAN','challenge','blue'):''}</div><p class="map-note" id="station-note" role="status"></p></div></div>`;focus()}
function sceneVisual(){return `<svg viewBox="0 0 360 145" role="img" aria-label="Seorang murid berasa takut apabila diganggu sekumpulan murid"><rect x="8" y="6" width="344" height="132" rx="25" fill="#e6f6ff"/><path d="M20 111H340" stroke="#bedff1" stroke-width="3"/><g fill="#3b84bf"><circle cx="67" cy="43" r="16"/><rect x="47" y="64" width="40" height="49" rx="16"/><circle cx="117" cy="49" r="14"/><rect x="99" y="68" width="36" height="45" rx="14"/><circle cx="164" cy="43" r="16"/><rect x="144" y="64" width="40" height="49" rx="16"/></g><path d="M189 65l34 12" stroke="#3b84bf" stroke-width="11" stroke-linecap="round"/><path d="M56 34h28v-18h-7l-6-8-5 8H56z" fill="#ffc947"/><g><circle cx="283" cy="56" r="18" fill="#f3c79c"/><path d="M266 53q0-27 27-18l10 18" fill="#465675"/><rect x="260" y="77" width="47" height="42" rx="15" fill="#8d79d4"/><circle cx="277" cy="57" r="2" fill="#355078"/><circle cx="290" cy="57" r="2" fill="#355078"/><path d="M278 68q6-6 12 0" fill="none" stroke="#91684f" stroke-width="2"/></g><path d="M232 35l-4-10m14 8 3-11m5 19 10-4" stroke="#efbb32" stroke-width="4" stroke-linecap="round"/></svg>`}
function steps(){const p=engine.snapshot();return `<div class="module-steps" aria-label="Kemajuan pembelajaran">${[0,1,2,3].map(i=>`<span class="${i<3&&p.learned.includes(i)?'done':''} ${i===lesson?'current':''}"></span>`).join('')}</div>`}
function learning(i){lesson=Math.max(0,Math.min(2,i));if(!engine.visit(lesson)){lesson=0;engine.visit(0)}save();const body=mount('learning');let content='';if(lesson===0)content=`<div class="learn-visual">${sceneVisual()}</div><p class="copy">${E.cards[0].text}</p>`;
if(lesson===1)content=`<div class="feature-grid">${[['♡','Menyakitkan atau menakutkan'],['↻','Berulang atau berpotensi berulang'],['⚖','Ketidakseimbangan kuasa']].map((a,n)=>`<button class="feature" data-feature="${n}" aria-expanded="false"><b aria-hidden="true">${a[0]}</b>${a[1]}</button>`).join('')}</div><p class="feature-note" id="feature-note" role="status">Sentuh setiap ciri untuk melihat contoh ringkas.</p>`;
if(lesson===2)content=`<div class="category"><b>BULI</b><span>Perbuatan menyakitkan atau menakutkan yang mempunyai ciri-ciri buli.</span></div><div class="category"><b>GURAUAN</b><span>Kedua-dua pihak selesa dan menghormati batas.</span></div><div class="category"><b>KONFLIK</b><span>Perselisihan antara pihak yang mempunyai kedudukan relatif seimbang.</span></div><p class="safety-note">Jika sesuatu perbuatan menyakitkan atau membuat kamu takut, dapatkan bantuan guru walaupun kamu tidak pasti sama ada itu buli.</p>`;
body.innerHTML=`${steps()}<div class="learning-layout"><div class="mentor"><img src="assets/${profile.avatar}-action.png" alt="Karakter pilihan kamu"></div><article class="learning-card w-glass"><div class="learning-top"><p class="w-kicker">NEXUS · KAD ${lesson+1} / 3</p>${button('◖ Dengar','audio','audio-button')}</div><h1 class="w-title">${E.cards[lesson].title}</h1><div class="lesson-content">${content}</div><div class="learning-nav">${button('‹ Sebelumnya',lesson===0?'intro':'previous')}${button(lesson===2?'Sedia untuk cabaran →':'Seterusnya →',lesson===2?'ready':'next','primary')}</div><p id="audio-note" class="map-note" role="status"></p></article></div>`;focus()}
function ready(){if(!engine.canChallenge())return learning(0);const body=mount('ready');body.innerHTML=`<div class="module-layout"><div class="nexus-scene"><img class="map-scene" src="assets/Peta_1_NEXUS.png" alt="Pulau NEXUS"><img class="scene-hero" src="assets/${profile.avatar}-action.png" alt=""></div><div class="intro-panel w-glass"><p class="w-kicker">3 KAD TELAH DILENGKAPKAN</p><h1 class="w-title">Kamu bersedia<br>untuk NEXUS SCAN!</h1><p class="w-sub">Kenal pasti <strong>buli, gurauan atau konflik</strong> dalam lima situasi. Kamu boleh mencuba semula sehingga berjaya.</p><p class="w-sub">Pilih sentuhan untuk terus bermain, atau kamera untuk memilih menggunakan tangan. Paparan kamera tidak dirakam atau dimuat naik.</p><div class="intro-cta">${button('MULA CABARAN AR','camera-challenge','primary')}${button('MOD SENTUHAN','challenge','blue')}</div></div></div>`;focus()}
function challenge(useCamera=false){if(!engine.canChallenge())return learning(0);if(engine.hasBadge())return success();engine.beginChallenge();save();const body=mount('challenge');body.innerHTML=`<div class="challenge" id="challenge"><video class="camera-video" id="nexus-video" autoplay playsinline muted hidden></video><div class="camera-shade"></div><div class="challenge-tools"><span class="mode-label" id="mode-label">NEXUS SCAN · SENTUHAN</span><div class="mode-tools">${button('◉ Kamera','camera')}${button('Sentuhan','touch')}${button('Kalibrasi semula','calibrate','','id="calibrate" hidden')}</div></div><div class="scan-area"><article class="scenario-card"><p class="scenario-kicker" id="scenario-kicker"></p><div class="scenario-head" id="scenario-progress"></div><h1 id="scenario-text"></h1></article><div class="answer-grid">${['BULI','GURAUAN','KONFLIK'].map(a=>`<button class="answer" data-answer="${a}" data-hand>${a}</button>`).join('')}</div><div class="challenge-feedback" id="challenge-feedback" role="status" aria-live="polite"><p>Pilih jawapan kamu.</p></div></div><p class="camera-status" id="camera-status">Semua situasi boleh dimainkan tanpa kamera.</p><div class="hand-cursor" id="hand-cursor" hidden aria-hidden="true"></div></div>`;paintQuestion();focus();if(useCamera)startCamera()}
function paintQuestion(){const n=engine.snapshot().solved;if(n>=5)return success();const q=E.scenarios[n];$('#scenario-kicker').textContent=`SITUASI ${n+1} / 5` ;$('#scenario-progress').innerHTML=E.scenarios.map((_,i)=>`<span class="${i<n?'done':''}"></span>`).join('');$('#scenario-text').textContent=q.text;world.querySelectorAll('[data-answer]').forEach(b=>b.disabled=false);$('#challenge-feedback').className='challenge-feedback';$('#challenge-feedback').innerHTML='<p>Pilih BULI, GURAUAN atau KONFLIK.</p>'}
function answer(value){if(view!=='challenge'||world.querySelector('[data-answer]')?.disabled)return;const result=engine.answer(value);if(!result.accepted)return;save();const f=$('#challenge-feedback');f.className='challenge-feedback '+(result.correct?'correct':'wrong');if(result.correct){world.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);f.innerHTML=`<p><strong>Bagus!</strong> ${result.feedback}</p>${button(result.complete?'Terima lencana ✦':'Situasi seterusnya →',result.complete?'success':'next-question','primary','data-hand')}`;if(result.complete)stopCamera()}else f.innerHTML=`<p><strong>Mari cuba lagi.</strong> ${result.feedback} Pilih jawapan yang paling sesuai.</p>`}
async function startCamera(){if(view!=='challenge')return;stopCamera();const video=$('#nexus-video');const instance=new root.SafeHandController({video,cursor:$('#hand-cursor'),status:text=>{if(view!=='challenge'||$('#nexus-video')!==video)return;$('#camera-status').textContent=text;$('#challenge').classList.toggle('camera-on',!video.hidden);$('#mode-label').textContent=video.hidden?'NEXUS SCAN · SENTUHAN':'NEXUS SCAN · KAMERA';$('#calibrate').hidden=video.hidden},onPinch:target=>target.click()});controller=instance;await instance.start();if(view==='challenge'&&controller===instance){$('#challenge').classList.toggle('camera-on',!video.hidden);$('#calibrate').hidden=video.hidden}}
function success(){if(!engine.hasBadge())return mapGrid();const body=mount('success');body.innerHTML=`<div class="success"><div class="success-art"><img src="assets/${profile.avatar}-action.png" alt="Karakter pilihan meraikan kejayaan"><div class="badge-orb" aria-label="Lencana Mata Bijak"><b aria-hidden="true">◉</b><span>MATA BIJAK</span></div></div><div class="success-panel w-glass"><p class="w-kicker">MISI NEXUS SELESAI</p><h1 class="w-title">Tahniah,<br>${esc(profile.name)}!</h1><p class="w-sub">Kamu telah berjaya menyelesaikan misi NEXUS dan memperoleh <strong>Lencana Mata Bijak!</strong></p><div class="success-actions">${button('✦ Lihat lencana','badge','primary')}${button('Kembali ke peta','maps')}${button('Teruskan ke CYBER GRID →','cyber','blue')}</div><div id="badge-detail" class="badge-detail" hidden>✦ <strong>MATA BIJAK</strong><br>3 kad pembelajaran dan 5 situasi telah selesai.<br>CYBER GRID kini dibuka.</div></div></div><div class="confetti" aria-hidden="true">${Array.from({length:16},(_,i)=>`<i style="--x:${(i*17)%100}%;--c:${['#1688ed','#ffc83d','#59dfff','#8bcfb2'][i%4]};--d:${i*.06}s"></i>`).join('')}</div>`;focus()}
function cyber(){if(!engine.unlocked(1))return mapGrid();const body=mount('cyber');body.innerHTML=`<div class="module-layout"><div class="nexus-scene"><img class="map-scene" src="assets/Peta_2_CYBER_GRID.png" alt="Pulau CYBER GRID"></div><div class="intro-panel w-glass"><p class="w-kicker">PETA 02 TELAH DIBUKA</p><h1 class="w-title">CYBER GRID</h1><p class="w-sub">Lencana Mata Bijak telah membuka peta ini. Misi digital seterusnya sedang disiapkan.</p><p class="w-sub">Kamu boleh kembali ke peta utama atau ulang kaji NEXUS.</p><div class="intro-cta">${button('Kembali ke peta','maps','primary')}${button('Ulang kaji NEXUS','intro')}</div></div></div>`;focus()}
function audio(){if(!('speechSynthesis'in root)||!('SpeechSynthesisUtterance'in root)){$('#audio-note').textContent='Audio tidak disokong pada peranti ini. Kamu boleh membaca kad ini.';return}if(audioActive){stopAudio();$('#audio-note').textContent='Bacaan dihentikan.';return}stopAudio();const u=new SpeechSynthesisUtterance(E.cards[lesson].title+'. '+E.cards[lesson].text);u.lang='ms-MY';u.rate=.9;const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.toLowerCase()==='ms-my')||voices.find(v=>v.lang.toLowerCase().startsWith('ms'));if(voice)u.voice=voice;audioActive=true;$('#audio-note').textContent='Sedang membaca… Tekan Dengar untuk berhenti.';u.onend=()=>{audioActive=false;if(view==='learning'&&$('#audio-note'))$('#audio-note').textContent='Bacaan selesai.'};u.onerror=()=>{audioActive=false;if(view==='learning'&&$('#audio-note'))$('#audio-note').textContent='Audio belum tersedia. Teruskan dengan membaca kad.'};speechSynthesis.speak(u)}
function exit(){stopCamera();stopAudio();world.hidden=true;document.querySelector('main.app').inert=false;$('#choose').focus()}
world.addEventListener('click',e=>{const map=e.target.closest('[data-map]');if(map){const i=Number(map.dataset.map);if(!engine.unlocked(i)){$('#map-note').textContent=i===1?'Dapatkan Lencana Mata Bijak di NEXUS dahulu.':`Selesaikan ${E.maps[i-1].name} untuk membuka peta ini.`;return}return i===0?intro():cyber()}
const station=e.target.closest('[data-station]');if(station){const n=Number(station.dataset.station);if(n===3){if(engine.canChallenge())return ready();$('#station-note').textContent='Lengkapkan tiga kad pembelajaran dahulu.';return}if(n>0&&!engine.snapshot().learned.includes(n-1)){$('#station-note').textContent='Mulakan dengan stesen sebelumnya dahulu.';return}return learning(n)}
const feature=e.target.closest('[data-feature]');if(feature){const n=Number(feature.dataset.feature);world.querySelectorAll('[data-feature]').forEach(b=>b.setAttribute('aria-expanded',String(b===feature)));$('#feature-note').textContent=['Contoh: ejekan atau ugutan menyebabkan rakan sedih dan takut.','Contoh: perbuatan yang sama dilakukan berulang kali atau mungkin berlaku lagi.','Contoh: sekumpulan murid menggunakan kekuatan atau pengaruh untuk menguasai seorang rakan.'][n];return}
const ans=e.target.closest('[data-answer]');if(ans)return answer(ans.dataset.answer);
const act=e.target.closest('[data-action]')?.dataset.action;if(!act)return;
const actions={exit,maps:mapGrid,help:()=>infoPanel('help'),collection:()=>infoPanel('collection'),certificate:()=>infoPanel('certificate'),'welcome-audio':welcomeAudio,intro,learn:()=>learning(engine.snapshot().learned.length?Math.min(2,engine.snapshot().learned.length-1):0),previous:()=>learning(lesson-1),next:()=>learning(lesson+1),ready,challenge:()=>challenge(false),'camera-challenge':()=>challenge(true),camera:startCamera,touch:()=>{stopCamera();$('#challenge').classList.remove('camera-on');$('#mode-label').textContent='NEXUS SCAN · SENTUHAN';$('#calibrate').hidden=true;$('#camera-status').textContent='Mod sentuhan aktif. Kamera telah dihentikan.'},calibrate:()=>{controller?.recalibrate();$('#camera-status').textContent='Penunjuk ditetapkan semula. Angkat tangan, halakan telunjuk dan rapatkan jari untuk memilih.'},audio,'next-question':paintQuestion,success,badge:()=>{$('#badge-detail').hidden=!$('#badge-detail').hidden},cyber};actions[act]?.()});
world.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();view==='maps'||view==='notice'?exit():mapGrid();return}if(e.key==='Tab'){const focusable=[...world.querySelectorAll('button:not(:disabled),[tabindex="0"]')].filter(el=>!el.hidden&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||!focusable.includes(document.activeElement))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||!focusable.includes(document.activeElement))){e.preventDefault();first?.focus()}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();stopAudio();if(view==='challenge'&&!world.hidden&&$('#camera-status')){$('#challenge').classList.remove('camera-on');$('#mode-label').textContent='NEXUS SCAN · SENTUHAN';$('#calibrate').hidden=true;$('#camera-status').textContent='Kamera dihentikan apabila halaman ditinggalkan. Kamu boleh membukanya semula.'}}});root.addEventListener('pagehide',()=>{stopCamera();stopAudio()});
root.SafeWorld={open(p){profile={id:p.id,name:p.name,avatar:['arif','airis','faris','sara'].includes(p.avatar)?p.avatar:'arif',classroom:p.classroom||''};let raw;try{raw=JSON.parse(read('safe-nexus-v1:'+profile.id))}catch{}engine=E.create(raw);world.hidden=false;document.querySelector('main.app').inert=true;notice()},close:exit};
})(window);
